// .claude/settings.json — configuração típica de projeto profissional
{
  "model": "claude-opus-4-7",
  "effortLevel": "high",
  "defaultMode": "plan",
  "permissions": {
    "allow": [
      "Bash(git status)",
      "Bash(git diff:*)",
      "Bash(git log:*)",
      "Bash(git branch:*)",
      "Bash(npm test:*)",
      "Bash(npm run lint:*)",
      "Bash(npm run build:*)",
      "Read(**)",
      "Glob(**)",
      "Grep(**)",
      "Edit(src/**)",
      "Edit(tests/**)",
      "Edit(docs/**)"
    ],
    "deny": [
      "Bash(rm -rf:*)",
      "Bash(sudo:*)",
      "Bash(curl:*)",
      "Bash(npm publish:*)",
      "Bash(git push --force:*)",
      "Edit(.env*)",
      "Edit(**/secrets/**)",
      "Write(/etc/**)"
    ],
    "ask": [
      "Bash(git push:*)",
      "Bash(docker:*)",
      "Edit(package.json)",
      "Edit(Dockerfile)"
    ]
  },
  "sandbox": {
    "network": {
      "deniedDomains": ["pastebin.com", "transfer.sh", "*.ngrok.io"]
    }
  },
  "statusLine": {
    "type": "command",
    "command": "~/.claude/statusline.sh",
    "refreshInterval": 5000
  },
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [{ "type": "command", "command": ".claude/hooks/auto-lint.sh" }]
      }
    ],
    "Stop": [
      {
        "matcher": ".*",
        "hooks": [{ "type": "command", "command": ".claude/hooks/notify.sh" }]
      }
    ]
  }
}
